import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d as p,i as d,S as P}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"RIP 对照","description":"","frontmatter":{"title":"RIP 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rip.md","filePath":"cs/rip.md","lastUpdated":1789023840000}'),c={name:"cs/rip.md"};function h(I,a,B,E,_,A){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="rip-对照" tabindex="-1">RIP 对照 <a class="header-anchor" href="#rip-对照" aria-label="Permalink to &quot;RIP 对照&quot;">​</a></h1><div class="epigraph"><p>RIP 把到目的的距离收成跳数，定期推送整表；简单，但慢收敛、跳数上限 15，只适合对照，不适合当代骨干。</p><footer>—— 据 RFC 2453 RIP Version 2；主干距离向量与计数到无穷课整理</footer></div><p>主干<a href="/cs/distance-vector">距离向量</a> 与<a href="/cs/count-to-infinity">计数到无穷</a> 已讲 Bellman–Ford 病。<a href="/cs/isis">上一课</a> 是链路状态骨干。缺口是<strong>把 RIP 钉成对照物</strong>：RIPv2 的跳数、水平分割、毒性逆转、组播 224.0.0.9。本课不把 BGP 决策阶梯写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OSPF/IS-IS 用 LSDB 全局视图。RIP：邻居告诉我「我离某前缀 n 跳」，我加一。无穷=16，故直径不能大。定时器：更新、失效、垃圾回收，以十秒计，收敛远慢于 RSTP 握手，更慢于 IGP 的增量 SPF。认证可加，但不改算法。</p><p>不要把 RIP 的「跳」当成 OSPF 代价：一条 10G 与一条 64K 在 RIP 里可同为 1 跳。</p><p><span class="marginnote">RIPng 用于 IPv6，对象相同。本课不把 RIP 当推荐设计。教材保留它是为了理解 DV。</span></p><h3 id="跳数不是带宽" tabindex="-1">跳数不是带宽 <a class="header-anchor" href="#跳数不是带宽" aria-label="Permalink to &quot;跳数不是带宽&quot;">​</a></h3><p>16 为无穷，直径受限。水平分割缓解环，不消灭计数到无穷。当代骨干用链路状态；本课只对照向量病。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三列：RIP / OSPF / IS-IS：信息、收敛、度量、范围。画：收表 → 加一 → 选最小 → 再通告。水平分割：不把从某口学来的路由原路送回，减轻环，不消灭计数到无穷。</p>',11)),(e(),n(P,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NBR%5B%22%E9%82%BB%E5%B1%85%E8%B7%9D%E7%A6%BB%E5%90%91%E9%87%8F%22%5D%20--%3E%20ADD%5B%22%E5%8A%A0%E4%B8%80%E8%B7%B3%22%5D%0A%20%20ADD%20--%3E%20MIN%5B%22%E9%80%89%E6%9C%80%E5%B0%8F%22%5D%0A%20%20MIN%20--%3E%20ADV%5B%22%E5%86%8D%E9%80%9A%E5%91%8A%22%5D%0A%20%20ADV%20--%3E%20CTI%5B%22%E4%BB%8D%E5%8F%AF%E8%83%BD%E8%AE%A1%E6%95%B0%E5%88%B0%E6%97%A0%E7%A9%B7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为何主干还要这课：后课 BGP 也是向量（路径向量），但属性丰富、政策显式。RIP 是最简向量，用来记住：没有拓扑图时环与慢收敛是默认。LACP、巨帧与 RIP 无关。</p><p>与 MAC 学习对照：学习是过滤表，RIP 是路由表；两者都会因过时项转发错误，老化时间尺度不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 EIGRP 的 DUAL 全文。BGP 属性与决策是下一课。后课默认：域内当代用链路状态；RIP 仅对照。</p><p>小型实验室可用 RIP，互联网边界不行。</p><p>上一课留下的缺口在本课收口；「RIP 对照」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/bgp-attributes-decision">BGP 属性与决策</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RIP：跳数 DV，16 为无穷，收敛慢。</li><li>水平分割是缓解不是定理。</li><li>用来对照 OSPF/IS-IS 与后课 BGP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2453；距离向量主干课。</li></ul>',10))])}const u=o(c,[["render",h]]);export{m as __pageData,u as default};
